//! The DIFFERENTIAL GATE: Lean's own evaluation is the semantics
//! authority over the SHIPPED wasm. The manifest (artifact/diff.json) is
//! generated by the wasm-backend's oracle program — real Lean functions
//! evaluated over generated inputs; this test replays every row against
//! the emitted component via wasmtime. A backend bug = a failing row.
//! Plus the SABOTAGE CONTROL: the gate must be able to FAIL.

#![allow(
    clippy::disallowed_methods,
    reason = "tokio::test codegen, not our code"
)]

mod common;

use std::sync::Arc;
use std::sync::Mutex;

use common::demo_component_path;
use common::diff_json_path;
use common::drain::DrainTask;
use common::instantiate;
use common::user_val;
use guestlang_host::CapabilitySet;
use guestlang_host::HostEngine;
use guestlang_host::bindings::GatewayUser;
use wasmtime::component::Val;

fn manifest() -> Vec<serde_json::Value> {
    let rows: Vec<serde_json::Value> = serde_json::from_str(
        &std::fs::read_to_string(diff_json_path()).expect("run `just wasm-compile`"),
    )
    .expect("diff.json");
    assert!(
        rows.len() >= 100,
        "oracle generated only {} rows — vacuous",
        rows.len()
    );
    rows
}

/// Walk the section headers (id + size LEBs) and return the CODE
/// section's byte range (id 0x0A).
fn code_section(w: &[u8]) -> Option<(usize, usize)> {
    let mut i = 8; // magic + version
    while i < w.len() {
        let id = w[i];
        let mut j = i + 1;
        let mut len: usize = 0;
        let mut shift = 0;
        loop {
            let b = w[j];
            len |= ((b & 0x7F) as usize) << shift;
            j += 1;
            shift += 7;
            if b & 0x80 == 0 {
                break;
            }
        }
        if id == 0x0A {
            return Some((j, j + len));
        }
        i = j + len;
    }
    None
}

// ── the Oracle.lean mirror (GENERATED — byte-tied by `just gen`) ────
// CompareMode/ErrorId/Outcome/compare/ser_val (plus classify/verdict)
// are emitted by the oracle-mirror emitter (Oracle.lean's OracleMirror
// section, registered in schema-lang's coreEmitters) into
// generated/rust/oracle_mirror_generated.rs. The phase-1 HAND COPIES
// (the local enum mirrors below) were DELETED — this module IS the
// mirror, the same #[path] routing as oracle-runner's driver
// (crates/oracle-runner/src/main.rs). Regenerate with `just gen`;
// never hand-edit the generated file. The ser forms MUST match Lean's
// `resultOf` byte-for-byte (the differential duels pin it).
#[path = "../../../generated/rust/oracle_mirror_generated.rs"]
mod oracle_mirror;

use oracle_mirror::*;

#[test]
fn compare_mode_truth_table() {
    use CompareMode::*;
    let va = Outcome::value("42".into());
    let vb = Outcome::value("43".into());
    // FULL: identity AND payload byte-compare — a same-identity error
    // pair passes when the payloads are byte-equal too (Lean's
    // `.full, some e, some f => e == f && payloads equal` arm: a trap
    // vs a payload-free trap passes).
    assert!(compare(Full, &va, &va));
    assert!(!compare(Full, &va, &vb));
    assert!(!compare(Full, &va, &Outcome::trap()));
    assert!(compare(Full, &Outcome::trap(), &Outcome::trap()));
    // IDENTITY: error-ness compares; value payloads never read. (The
    // replay's single error identity is Trap, so Trap==Trap passes.)
    assert!(compare(Identity, &Outcome::trap(), &Outcome::trap()));
    assert!(compare(Identity, &va, &vb));
    assert!(!compare(Identity, &va, &Outcome::trap()));
    // IGNORE: an error on either side waives.
    assert!(compare(Ignore, &Outcome::trap(), &va));
    assert!(compare(Ignore, &va, &Outcome::trap()));
    assert!(compare(Ignore, &va, &va));
    assert!(!compare(Ignore, &va, &vb));
}

fn render_user(u: &GatewayUser) -> String {
    format!(
        "{{ id={}, name={}, email={}, tags=({}) }}",
        u.id,
        u.name,
        u.email,
        u.tags.join(",")
    )
}

#[tokio::test]
async fn engine_same_instance() -> Result<(), Box<dyn std::error::Error>> {
    // the real replay (kept separate from the sabotage control so a
    // sabotaged build can't mask the honest run)
    let rows = manifest();
    let engine = HostEngine::new()?;
    let component = engine.load_component_bytes(&std::fs::read(demo_component_path())?)?;
    let mut rt = instantiate(&engine, &component, CapabilitySet::NONE).await?;

    let mut failures: Vec<String> = Vec::new();
    // The record-ARG convention: a record-valued param's row args = the
    // FIELD VALUES FLAT (id, name, email, tags comma-joined) — the
    // manifest rows are List String, so the arg-builder ADAPTS the
    // shared `user_val` from the string row (the canonical ABI
    // flattens the user to u64 + 3×(ptr,len); wasmtime lowers the Val
    // tree the same way).
    fn user_record(strs: &[&str]) -> Val {
        user_val(
            strs[0].parse::<u64>().expect("user id"),
            strs[1],
            strs[2],
            &strs[3].split(',').collect::<Vec<_>>(),
        )
    }
    // The VARIANT-ARG convention: a variant-valued param's row args =
    // [discr, payload] — the canonical-ABI flat form. The discr = the
    // WIT case order (empty-cart=0, invalid-item=1, insufficient-funds=2);
    // the payload rides the joined i64 slot (u64 raw, f64 bits — the
    // wasm-side read of the f64 case is the constant arm, see the guest
    // impl).
    fn order_error_variant(strs: &[&str]) -> Val {
        match strs[0] {
            "0" => Val::Variant("empty-cart".into(), None),
            "1" => Val::Variant(
                "invalid-item".into(),
                Some(Box::new(Val::U64(
                    strs[1].parse::<u64>().expect("invalid-item payload"),
                ))),
            ),
            _ => Val::Variant(
                "insufficient-funds".into(),
                Some(Box::new(Val::Float64(
                    strs[1].parse::<f64>().expect("insufficient-funds payload"),
                ))),
            ),
        }
    }
    // The WITNESS-BYTES convention (verify-witness, W9.6): the row arg
    // = the committed witness bytes, comma-joined decimal u8s — rebuilt
    // as the canonical list<u8> Val tree (the lift copies the bytes
    // into guest memory; the bytesParam adapter re-chains them).
    fn witness_bytes(s: &str) -> Val {
        Val::List(
            s.split(',')
                .map(|b| Val::U8(b.parse::<u8>().expect("witness byte")))
                .collect(),
        )
    }
    for row in &rows {
        let f = row["fn"].as_str().expect("fn");
        let strs: Vec<&str> = row["args"]
            .as_array()
            .expect("args")
            .iter()
            .map(|a| a.as_str().expect("arg str"))
            .collect();
        let args: Vec<Val> = if f == "user-valid" || f == "user-complete" {
            vec![user_record(&strs)]
        } else if f == "order-error-valid" {
            vec![order_error_variant(&strs)]
        } else if f == "verify-witness" {
            vec![witness_bytes(strs[0])]
        } else {
            strs.iter()
                .enumerate()
                .map(|(i, a)| match (f, i, *a) {
                    ("pick", 0, "0" | "1") => Val::Bool(*a == "1"),
                    (_, _, s) => Val::U64(s.parse::<u64>().expect("u64 arg")),
                })
                .collect()
        };
        // W6.3 ph1: every row binds Full today (the wire carries no
        // mode column yet — Oracle.lean's `modeOf` is the Lean-side
        // binding; this constant is its mirror until phase 2).
        let mode = CompareMode::Full;
        let expected = Outcome::value(row["expected"].as_str().expect("expected").to_string());
        let got: Outcome = if f == "watch-counts" || f == "watch-users" {
            // the STREAM rows: the call + the drain in ONE event loop —
            // the consumer must be a background task while the loop
            // pumps the guest's pending write (a post-call drain never
            // gets polled — the loop already exited).
            let out = Arc::new(Mutex::new(Vec::new()));
            let instance = rt.instance().expect("instance").clone();
            let is_counts = f == "watch-counts";
            let fname = f.to_string();
            let sink = out.clone();
            rt.store_mut()
                .run_concurrent(async move |accessor| {
                    let f =
                        accessor.with(|access| instance.get_func(access, &fname).expect("export"));
                    let mut results = [if is_counts {
                        Val::U64(0)
                    } else {
                        Val::List(vec![])
                    }];
                    f.call_concurrent(accessor, &args, &mut results).await?;
                    let any = match results[0].clone() {
                        Val::Stream(a) => a,
                        other => panic!("{fname}: not a stream: {other:?}"),
                    };
                    if is_counts {
                        let reader = any.try_into_stream_reader::<u64>()?;
                        accessor
                            .spawn(DrainTask::new(reader, sink, |v: &u64| v.to_string()))?
                            .await;
                    } else {
                        let reader = any.try_into_stream_reader::<GatewayUser>()?;
                        accessor
                            .spawn(DrainTask::new(
                                reader,
                                sink,
                                render_user as fn(&GatewayUser) -> String,
                            ))?
                            .await;
                    }
                    Ok::<(), wasmtime::Error>(())
                })
                .await??;
            let items = out.lock().unwrap();
            Outcome::value(format!(
                "({})",
                items
                    .iter()
                    .map(|v| v.to_string())
                    .collect::<Vec<_>>()
                    .join(",")
            ))
        } else {
            match rt.call(f, &args).await {
                Ok(results) => match results.into_iter().next() {
                    Some(v) => Outcome::value(ser_val(&v)),
                    None => Outcome::value("?".into()),
                },
                Err(e) => {
                    // the replay's error identity: Trap (payload-free).
                    // Under Full a value-vs-trap always fails;
                    // Ignore/Identity rows decide through the mode
                    // once the wire carries them (phase 2).
                    if !compare(mode, &expected, &Outcome::trap()) {
                        failures.push(format!("{f} {:?}: TRAP {e}", row["args"]));
                    }
                    continue;
                }
            }
        };
        if !compare(mode, &expected, &got) {
            let Outcome {
                error: None,
                payload: exp,
            } = &expected
            else {
                unreachable!("manifest expecteds are values")
            };
            let Outcome {
                error: None,
                payload: got_str,
            } = &got
            else {
                unreachable!("non-trap outcomes are values")
            };
            failures.push(format!(
                "{f} {:?}: expected {exp}, got {got_str}",
                row["args"]
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} differential failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
    Ok(())
}

/// The sabotage control: flip `i64.add` (0x7C) → `i64.mul` (0x7E) inside
/// the CODE section — the module still loads, still runs, but computes
/// wrong — the differential replay MUST catch it.
#[tokio::test]
async fn the_gate_catches_sabotage() -> Result<(), Box<dyn std::error::Error>> {
    // the component embeds the core module — the pattern appears ONCE
    // (adder's body differs: local.get 1 not 0); the flip changes no
    // lengths, so the component structure stays valid
    let mut wasm = std::fs::read(demo_component_path())?;
    let pat: [u8; 10] = [0x20, 0x00, 0x20, 0x00, 0x7C, 0x21, 0x01, 0x20, 0x01, 0x0F];
    let pos = wasm
        .windows(10)
        .position(|w| *w == pat)
        .expect("double's add pattern not found");
    wasm[pos + 4] = 0x7E; // i64.add → i64.mul

    let engine = HostEngine::new()?;
    let component = engine.load_component_bytes(&wasm)?;
    let mut rt = instantiate(&engine, &component, CapabilitySet::NONE).await?;
    let got = rt.call("double", &[Val::U64(21)]).await?;
    let Val::U64(v) = &got[0] else {
        panic!("non-u64")
    };
    assert_ne!(
        v.to_string(),
        "42",
        "the sabotage didn't change the result — the control is vacuous"
    );
    assert_eq!(v.to_string(), "441", "the sabotage flipped the wrong op");
    Ok(())
}
